"""Reviewed NL -> SQL pairs for the Halcyon demo (57 pairs).

`demo rq-check halcyon` executes every pair against DuckDB (and Snowflake with
--snowflake) and writes build/reviewed-queries.csv in Wisdom's import format.
NL text must not contain commas; SQL uses upper-case identifiers with
double-quoted object names.
"""
from demo_creator.reviewed_queries import Registry

rq = Registry()
add = rq.add

# ---------------------------------------------------------------- basics
add("Which distribution centers does Halcyon operate and which are cold chain capable?",
    'SELECT DC_ID, DC_NAME, CITY, STATE, REGION, COLD_CHAIN_CAPABLE, ULTRA_COLD_CAPABLE FROM "DISTRIBUTION_CENTERS" ORDER BY DC_ID')
add("List our strategic customers with their contract value and renewal date.",
    'SELECT CUSTOMER_NAME, CUSTOMER_TYPE, REGION, ANNUAL_CONTRACT_VALUE, CONTRACT_RENEWAL_DATE, ACCOUNT_MANAGER FROM "CUSTOMERS" WHERE CUSTOMER_TIER = \'STRATEGIC\' ORDER BY ANNUAL_CONTRACT_VALUE DESC')
add("How many customers do we have by type and tier?",
    'SELECT CUSTOMER_TYPE, CUSTOMER_TIER, COUNT(*) AS CUSTOMER_COUNT, SUM(ANNUAL_CONTRACT_VALUE) AS TOTAL_ACV FROM "CUSTOMERS" WHERE IS_ACTIVE = TRUE GROUP BY CUSTOMER_TYPE, CUSTOMER_TIER ORDER BY CUSTOMER_TYPE, CUSTOMER_TIER')
add("Which products are on manufacturer allocation?",
    'SELECT P.PRODUCT_NAME, P.GENERIC_NAME, P.THERAPEUTIC_CLASS, M.MANUFACTURER_NAME, P.STORAGE_CLASS, P.WAC_UNIT_PRICE FROM "PRODUCTS" AS P JOIN "MANUFACTURERS" AS M ON P.MANUFACTURER_ID = M.MANUFACTURER_ID WHERE P.IS_ALLOCATED = TRUE ORDER BY P.THERAPEUTIC_CLASS, P.PRODUCT_NAME')
add("What is our total shipped revenue by therapeutic class?",
    'SELECT THERAPEUTIC_CLASS, ROUND(SUM(SHIPPED_REVENUE), 2) AS SHIPPED_REVENUE, COUNT(*) AS LINE_COUNT FROM "V_ORDER_LINE_DETAIL" GROUP BY THERAPEUTIC_CLASS ORDER BY SHIPPED_REVENUE DESC')
add("Who are our top 10 customers by shipped revenue in 2026?",
    'SELECT CUSTOMER_NAME, CUSTOMER_TIER, ROUND(SUM(SHIPPED_REVENUE), 2) AS SHIPPED_REVENUE FROM "V_ORDER_LINE_DETAIL" WHERE ORDER_DATE >= DATE \'2026-01-01\' GROUP BY CUSTOMER_NAME, CUSTOMER_TIER ORDER BY SHIPPED_REVENUE DESC LIMIT 10')
add("What is our overall line fill rate this year?",
    'SELECT ROUND(SUM(IS_LINE_FILLED_COMPLETE) / NULLIF(COUNT(*), 0), 4) AS LINE_FILL_RATE, ROUND(SUM(QTY_SHIPPED) / NULLIF(SUM(QTY_ORDERED), 0), 4) AS UNIT_FILL_RATE, COUNT(*) AS LINE_COUNT FROM "V_ORDER_LINE_DETAIL" WHERE ORDER_DATE >= DATE \'2026-01-01\' AND LINE_STATUS <> \'CANCELLED\'')
add("Show monthly line fill rate across all customers for 2026.",
    'SELECT ORDER_MONTH, ROUND(SUM(IS_LINE_FILLED_COMPLETE) / NULLIF(COUNT(*), 0), 4) AS LINE_FILL_RATE, COUNT(*) AS LINE_COUNT FROM "V_ORDER_LINE_DETAIL" WHERE ORDER_DATE >= DATE \'2026-01-01\' AND LINE_STATUS <> \'CANCELLED\' GROUP BY ORDER_MONTH ORDER BY ORDER_MONTH')

# ---------------------------------------------------------------- renewal risk / Bayview
add("Which customers renewing in the next 120 days show the highest operational risk?",
    'SELECT CUSTOMER_NAME, CUSTOMER_TIER, ANNUAL_CONTRACT_VALUE, CONTRACT_RENEWAL_DATE, DAYS_TO_RENEWAL, OPERATIONAL_RISK_SCORE, TOP_RISK_REASON, RECENT_LINE_FILL_RATE, PRIOR_LINE_FILL_RATE, OPEN_BACKORDERS_OVER_14D, OPEN_HIGH_SEVERITY_CASES FROM "V_CUSTOMER_HEALTH" WHERE DAYS_TO_RENEWAL BETWEEN 0 AND 120 ORDER BY OPERATIONAL_RISK_SCORE DESC')
add("Which customers have the highest operational risk score right now?",
    'SELECT CUSTOMER_NAME, CUSTOMER_TIER, OPERATIONAL_RISK_SCORE, TOP_RISK_REASON, FILL_RATE_CHANGE, OPEN_BACKORDERS_OVER_14D, OPEN_HIGH_SEVERITY_CASES, DISCRETIONARY_VALUE_CHANGE_PCT, DAYS_TO_RENEWAL FROM "V_CUSTOMER_HEALTH" ORDER BY OPERATIONAL_RISK_SCORE DESC LIMIT 15')
add("Give me the full operational health picture for Bayview Regional Health.",
    'SELECT * FROM "V_CUSTOMER_HEALTH" WHERE CUSTOMER_NAME = \'Bayview Regional Health\'')
add("How has Bayview Regional Health fill rate changed by therapeutic class over the last 8 weeks versus the prior 8 weeks?",
    """SELECT THERAPEUTIC_CLASS,
       ROUND(SUM(CASE WHEN ORDER_DATE >= DATE '2026-07-27' THEN IS_LINE_FILLED_COMPLETE END) / NULLIF(SUM(CASE WHEN ORDER_DATE >= DATE '2026-07-27' THEN 1 END), 0), 4) AS RECENT_LINE_FILL_RATE,
       ROUND(SUM(CASE WHEN ORDER_DATE < DATE '2026-07-27' THEN IS_LINE_FILLED_COMPLETE END) / NULLIF(SUM(CASE WHEN ORDER_DATE < DATE '2026-07-27' THEN 1 END), 0), 4) AS PRIOR_LINE_FILL_RATE,
       COUNT(*) AS LINE_COUNT
FROM "V_ORDER_LINE_DETAIL"
WHERE CUSTOMER_NAME = 'Bayview Regional Health' AND ORDER_DATE >= DATE '2026-06-01' AND ORDER_DATE < DATE '2026-09-21' AND LINE_STATUS <> 'CANCELLED'
GROUP BY THERAPEUTIC_CLASS
ORDER BY RECENT_LINE_FILL_RATE""")
add("Show Bayview Regional Health monthly line fill rate for Vanterra versus everything else in 2026.",
    """SELECT ORDER_MONTH,
       CASE WHEN PRODUCT_NAME = 'Vanterra' THEN 'Vanterra' ELSE 'All other products' END AS PRODUCT_GROUP,
       ROUND(SUM(IS_LINE_FILLED_COMPLETE) / NULLIF(COUNT(*), 0), 4) AS LINE_FILL_RATE,
       COUNT(*) AS LINE_COUNT
FROM "V_ORDER_LINE_DETAIL"
WHERE CUSTOMER_NAME = 'Bayview Regional Health' AND ORDER_DATE >= DATE '2026-01-01' AND LINE_STATUS <> 'CANCELLED'
GROUP BY ORDER_MONTH, PRODUCT_GROUP
ORDER BY ORDER_MONTH, PRODUCT_GROUP""")
add("What are the open backorders for Bayview Regional Health and how old are they?",
    'SELECT BACKORDER_ID, BACKORDER_DATE, DAYS_OPEN, AGING_BUCKET, PRODUCT_NAME, THERAPEUTIC_CLASS, QTY_BACKORDERED, BACKORDER_VALUE_WAC, REASON_CODE, EXPECTED_RELEASE_DATE FROM "V_BACKORDER_AGING" WHERE CUSTOMER_NAME = \'Bayview Regional Health\' ORDER BY DAYS_OPEN DESC')
add("What open service cases does Bayview Regional Health have and which were escalated to executives?",
    'SELECT CASE_ID, OPENED_DATE, CASE_TYPE, SEVERITY, STATUS, ESCALATED_TO_EXEC, RELATED_BACKORDER_ID, CASE_SUMMARY FROM "SERVICE_CASES" WHERE CUSTOMER_ID = \'CUST-0001\' AND STATUS <> \'CLOSED\' ORDER BY OPENED_DATE DESC')
add("Has Bayview Regional Health reduced ordering of products that are not on allocation since late July?",
    """SELECT CASE WHEN ORDER_DATE >= DATE '2026-07-27' THEN 'Recent 8 weeks' ELSE 'Prior 8 weeks' END AS PERIOD,
       ROUND(SUM(CASE WHEN IS_ALLOCATED = FALSE THEN ORDERED_VALUE_WAC ELSE 0 END), 2) AS NON_ALLOCATED_ORDERED_VALUE_WAC,
       ROUND(SUM(CASE WHEN IS_ALLOCATED = TRUE THEN ORDERED_VALUE_WAC ELSE 0 END), 2) AS ALLOCATED_ORDERED_VALUE_WAC,
       COUNT(*) AS LINE_COUNT
FROM "V_ORDER_LINE_DETAIL"
WHERE CUSTOMER_NAME = 'Bayview Regional Health' AND ORDER_DATE >= DATE '2026-06-01' AND ORDER_DATE < DATE '2026-09-21' AND LINE_STATUS <> 'CANCELLED'
GROUP BY PERIOD
ORDER BY PERIOD DESC""")
add("Show Bayview Regional Health weekly ordered value for non allocated products since June.",
    """SELECT C.WEEK_START_DATE,
       ROUND(SUM(L.ORDERED_VALUE_WAC), 2) AS NON_ALLOCATED_ORDERED_VALUE_WAC,
       COUNT(*) AS LINE_COUNT
FROM "V_ORDER_LINE_DETAIL" AS L
JOIN "CALENDAR" AS C ON C.CALENDAR_DATE = L.ORDER_DATE
WHERE L.CUSTOMER_NAME = 'Bayview Regional Health' AND L.IS_ALLOCATED = FALSE AND L.ORDER_DATE >= DATE '2026-06-01' AND C.IS_COMPLETE_WEEK = TRUE AND L.LINE_STATUS <> 'CANCELLED'
GROUP BY C.WEEK_START_DATE
ORDER BY C.WEEK_START_DATE""")

# ---------------------------------------------------------------- allocation / Vanterra
add("How has the Veltrix allocation of Vanterra to Halcyon changed month by month in 2026?",
    'SELECT PERIOD_MONTH, MAX(HALCYON_TOTAL_ALLOCATION_UNITS) AS HALCYON_ALLOCATION_UNITS, SUM(CUSTOMER_REQUESTED_UNITS) AS REQUESTED_UNITS, SUM(CUSTOMER_ALLOCATED_UNITS) AS ALLOCATED_UNITS, SUM(CUSTOMER_CONSUMED_UNITS) AS CONSUMED_UNITS, SUM(SHORTFALL_UNITS) AS SHORTFALL_UNITS FROM "V_ALLOCATION_UTILIZATION" WHERE PRODUCT_NAME = \'Vanterra\' AND PERIOD_MONTH >= DATE \'2026-01-01\' GROUP BY PERIOD_MONTH ORDER BY PERIOD_MONTH')
add("Which customers have the largest Vanterra allocation shortfall since August?",
    'SELECT CUSTOMER_NAME, CUSTOMER_TIER, CONTRACT_RENEWAL_DATE, SUM(CUSTOMER_REQUESTED_UNITS) AS REQUESTED_UNITS, SUM(CUSTOMER_ALLOCATED_UNITS) AS ALLOCATED_UNITS, SUM(SHORTFALL_UNITS) AS SHORTFALL_UNITS, ROUND(SUM(SHORTFALL_VALUE_WAC), 2) AS SHORTFALL_VALUE_WAC FROM "V_ALLOCATION_UTILIZATION" WHERE PRODUCT_NAME = \'Vanterra\' AND PERIOD_MONTH >= DATE \'2026-08-01\' GROUP BY CUSTOMER_NAME, CUSTOMER_TIER, CONTRACT_RENEWAL_DATE ORDER BY SHORTFALL_UNITS DESC LIMIT 10')
add("Show Bayview Regional Health Vanterra requested versus allocated versus consumed units by month.",
    'SELECT PERIOD_MONTH, CUSTOMER_REQUESTED_UNITS, CUSTOMER_ALLOCATED_UNITS, CUSTOMER_CONSUMED_UNITS, UTILIZATION_PCT, SHORTFALL_UNITS, ALLOCATION_BASIS FROM "V_ALLOCATION_UTILIZATION" WHERE CUSTOMER_NAME = \'Bayview Regional Health\' AND PRODUCT_NAME = \'Vanterra\' AND PERIOD_MONTH >= DATE \'2026-01-01\' ORDER BY PERIOD_MONTH')
add("What share of the Vanterra allocation went to each customer in September and how did their requests compare?",
    'SELECT CUSTOMER_NAME, CUSTOMER_TIER, CUSTOMER_ALLOCATED_UNITS, CUSTOMER_REQUESTED_UNITS, SHORTFALL_UNITS, ROUND(CUSTOMER_ALLOCATED_UNITS / NULLIF(HALCYON_TOTAL_ALLOCATION_UNITS, 0), 4) AS SHARE_OF_HALCYON_ALLOCATION FROM "V_ALLOCATION_UTILIZATION" WHERE PRODUCT_NAME = \'Vanterra\' AND PERIOD_MONTH = DATE \'2026-09-01\' ORDER BY CUSTOMER_ALLOCATED_UNITS DESC')
add("Which customers are using less than 60 percent of their Vanterra allocation this month?",
    'SELECT CUSTOMER_NAME, CUSTOMER_TIER, CUSTOMER_ALLOCATED_UNITS, CUSTOMER_REQUESTED_UNITS, CUSTOMER_CONSUMED_UNITS, UTILIZATION_PCT, CUSTOMER_ALLOCATED_UNITS - CUSTOMER_CONSUMED_UNITS AS UNUSED_UNITS, ALLOCATION_BASIS FROM "V_ALLOCATION_UTILIZATION" WHERE PRODUCT_NAME = \'Vanterra\' AND PERIOD_MONTH = DATE \'2026-09-01\' AND UTILIZATION_PCT < 60 ORDER BY UNUSED_UNITS DESC')
add("How many unused Vanterra units could be reallocated from low utilization customers each month since June?",
    'SELECT PERIOD_MONTH, COUNT(*) AS DONOR_CUSTOMERS, SUM(CUSTOMER_ALLOCATED_UNITS - CUSTOMER_CONSUMED_UNITS) AS UNUSED_UNITS FROM "V_ALLOCATION_UTILIZATION" WHERE PRODUCT_NAME = \'Vanterra\' AND PERIOD_MONTH >= DATE \'2026-06-01\' AND UTILIZATION_PCT < 60 GROUP BY PERIOD_MONTH ORDER BY PERIOD_MONTH')
add("Which allocated products have the most shortfall across all customers this quarter?",
    'SELECT PRODUCT_NAME, THERAPEUTIC_CLASS, MANUFACTURER_NAME, SUM(CUSTOMER_REQUESTED_UNITS) AS REQUESTED_UNITS, SUM(CUSTOMER_ALLOCATED_UNITS) AS ALLOCATED_UNITS, SUM(SHORTFALL_UNITS) AS SHORTFALL_UNITS, ROUND(SUM(SHORTFALL_VALUE_WAC), 2) AS SHORTFALL_VALUE_WAC FROM "V_ALLOCATION_UTILIZATION" WHERE PERIOD_MONTH >= DATE \'2026-07-01\' GROUP BY PRODUCT_NAME, THERAPEUTIC_CLASS, MANUFACTURER_NAME ORDER BY SHORTFALL_UNITS DESC')

# ---------------------------------------------------------------- backorders
add("How many backorders are open right now by aging bucket and what are they worth?",
    'SELECT AGING_BUCKET, COUNT(*) AS OPEN_BACKORDERS, SUM(QTY_BACKORDERED) AS UNITS, ROUND(SUM(BACKORDER_VALUE_WAC), 2) AS VALUE_WAC FROM "V_BACKORDER_AGING" GROUP BY AGING_BUCKET ORDER BY AGING_BUCKET')
add("Which customers have the most backorders open longer than 14 days?",
    'SELECT CUSTOMER_NAME, CUSTOMER_TIER, CONTRACT_RENEWAL_DATE, COUNT(*) AS AGED_BACKORDERS, MAX(DAYS_OPEN) AS OLDEST_DAYS, ROUND(SUM(BACKORDER_VALUE_WAC), 2) AS VALUE_WAC FROM "V_BACKORDER_AGING" WHERE DAYS_OPEN > 14 GROUP BY CUSTOMER_NAME, CUSTOMER_TIER, CONTRACT_RENEWAL_DATE ORDER BY AGED_BACKORDERS DESC LIMIT 10')
add("What are the reasons behind our open backorders?",
    'SELECT REASON_CODE, COUNT(*) AS OPEN_BACKORDERS, SUM(QTY_BACKORDERED) AS UNITS, ROUND(SUM(BACKORDER_VALUE_WAC), 2) AS VALUE_WAC, ROUND(AVG(DAYS_OPEN), 1) AS AVG_DAYS_OPEN FROM "V_BACKORDER_AGING" GROUP BY REASON_CODE ORDER BY OPEN_BACKORDERS DESC')
add("Do backorders older than 14 days drive our high severity service cases?",
    """SELECT CASE WHEN B.DAYS_OPEN > 14 THEN 'Backorder over 14 days' ELSE 'Backorder 14 days or less' END AS BACKORDER_AGE,
       COUNT(*) AS HIGH_SEVERITY_CASES,
       SUM(CASE WHEN C.ESCALATED_TO_EXEC THEN 1 ELSE 0 END) AS EXEC_ESCALATIONS
FROM "SERVICE_CASES" AS C
JOIN "BACKORDERS" AS B ON B.BACKORDER_ID = C.RELATED_BACKORDER_ID
WHERE C.SEVERITY IN ('HIGH', 'CRITICAL')
GROUP BY BACKORDER_AGE
ORDER BY HIGH_SEVERITY_CASES DESC""")
add("Show the monthly trend of new backorders by reason in 2026.",
    'SELECT DATE_TRUNC(\'MONTH\', BACKORDER_DATE) AS BACKORDER_MONTH, REASON_CODE, COUNT(*) AS BACKORDERS, ROUND(SUM(BACKORDER_VALUE_WAC), 2) AS VALUE_WAC FROM "BACKORDERS" WHERE BACKORDER_DATE >= DATE \'2026-01-01\' GROUP BY BACKORDER_MONTH, REASON_CODE ORDER BY BACKORDER_MONTH, REASON_CODE')

# ---------------------------------------------------------------- cold chain
add("Compare cold chain excursion rates across distribution centers for refrigerated product in July and August 2026.",
    'SELECT DC_ID, SUM(READINGS) AS READINGS, SUM(EXCURSIONS) AS EXCURSIONS, ROUND(SUM(EXCURSIONS) / NULLIF(SUM(READINGS), 0), 4) AS EXCURSION_RATE, ROUND(SUM(VALUE_QUARANTINED_OR_DESTROYED_WAC), 2) AS VALUE_QUARANTINED_OR_DESTROYED_WAC FROM "V_COLD_CHAIN_EXCURSIONS" WHERE STORAGE_CLASS = \'REFRIGERATED_2_8C\' AND EVENT_MONTH >= DATE \'2026-07-01\' AND EVENT_MONTH < DATE \'2026-09-01\' GROUP BY DC_ID ORDER BY EXCURSION_RATE DESC')
add("Show the monthly cold chain excursion rate at the Memphis DC for refrigerated product in 2026.",
    'SELECT EVENT_MONTH, SUM(READINGS) AS READINGS, SUM(EXCURSIONS) AS EXCURSIONS, ROUND(SUM(EXCURSIONS) / NULLIF(SUM(READINGS), 0), 4) AS EXCURSION_RATE, SUM(MAJOR_EXCURSIONS) AS MAJOR_EXCURSIONS, SUM(CRITICAL_EXCURSIONS) AS CRITICAL_EXCURSIONS, ROUND(SUM(VALUE_QUARANTINED_OR_DESTROYED_WAC), 2) AS VALUE_QUARANTINED_OR_DESTROYED_WAC FROM "V_COLD_CHAIN_EXCURSIONS" WHERE DC_ID = \'DC-MEM\' AND STORAGE_CLASS = \'REFRIGERATED_2_8C\' AND EVENT_MONTH >= DATE \'2026-01-01\' GROUP BY EVENT_MONTH ORDER BY EVENT_MONTH')
add("At which stage are Memphis excursions happening since June?",
    'SELECT STAGE, SUM(READINGS) AS READINGS, SUM(EXCURSIONS) AS EXCURSIONS, ROUND(SUM(EXCURSIONS) / NULLIF(SUM(READINGS), 0), 4) AS EXCURSION_RATE FROM "V_COLD_CHAIN_EXCURSIONS" WHERE DC_ID = \'DC-MEM\' AND STORAGE_CLASS = \'REFRIGERATED_2_8C\' AND EVENT_MONTH >= DATE \'2026-06-01\' GROUP BY STAGE ORDER BY EXCURSION_RATE DESC')
add("Compare packout excursion rates by packaging type at Memphis since June.",
    'SELECT PACKAGING_TYPE, SUM(READINGS) AS READINGS, SUM(EXCURSIONS) AS EXCURSIONS, ROUND(SUM(EXCURSIONS) / NULLIF(SUM(READINGS), 0), 4) AS EXCURSION_RATE, SUM(MAJOR_EXCURSIONS) AS MAJOR_EXCURSIONS, SUM(CRITICAL_EXCURSIONS) AS CRITICAL_EXCURSIONS, ROUND(SUM(VALUE_QUARANTINED_OR_DESTROYED_WAC), 2) AS VALUE_QUARANTINED_OR_DESTROYED_WAC FROM "V_COLD_CHAIN_EXCURSIONS" WHERE DC_ID = \'DC-MEM\' AND STAGE = \'PACKOUT\' AND STORAGE_CLASS = \'REFRIGERATED_2_8C\' AND EVENT_MONTH >= DATE \'2026-06-01\' GROUP BY PACKAGING_TYPE ORDER BY EXCURSION_RATE DESC')
add("When did Memphis start using gel pack packaging for refrigerated shipments?",
    'SELECT DATE_TRUNC(\'MONTH\', SHIP_DATE) AS SHIP_MONTH, PACKAGING_TYPE, COUNT(*) AS SHIPMENTS FROM "SHIPMENTS" WHERE DC_ID = \'DC-MEM\' AND COLD_CHAIN_REQUIRED = TRUE AND PACKAGING_TYPE IN (\'GEL_PACK_STD\', \'PHASE_CHANGE_48H\') AND SHIP_DATE >= DATE \'2026-01-01\' GROUP BY SHIP_MONTH, PACKAGING_TYPE ORDER BY SHIP_MONTH, PACKAGING_TYPE')
add("How much product value has been quarantined or destroyed after excursions by DC since June?",
    'SELECT DC_ID, SUM(EXCURSIONS) AS EXCURSIONS, ROUND(SUM(VALUE_QUARANTINED_OR_DESTROYED_WAC), 2) AS VALUE_QUARANTINED_OR_DESTROYED_WAC, ROUND(SUM(VALUE_DESTROYED_WAC), 2) AS VALUE_DESTROYED_WAC FROM "V_COLD_CHAIN_EXCURSIONS" WHERE EVENT_MONTH >= DATE \'2026-06-01\' GROUP BY DC_ID ORDER BY VALUE_QUARANTINED_OR_DESTROYED_WAC DESC')
add("Which customers received the most major or critical excursion shipments from Memphis since June?",
    """SELECT C.CUSTOMER_NAME, C.CUSTOMER_TIER, COUNT(*) AS MAJOR_OR_CRITICAL_EXCURSIONS, ROUND(SUM(E.VALUE_AFFECTED_WAC), 2) AS VALUE_AFFECTED_WAC
FROM "COLD_CHAIN_EVENTS" AS E
JOIN "CUSTOMERS" AS C ON C.CUSTOMER_ID = E.CUSTOMER_ID
WHERE E.DC_ID = 'DC-MEM' AND E.IS_EXCURSION = TRUE AND E.EXCURSION_SEVERITY IN ('MAJOR', 'CRITICAL') AND E.EVENT_DATE >= DATE '2026-06-01'
GROUP BY C.CUSTOMER_NAME, C.CUSTOMER_TIER
ORDER BY MAJOR_OR_CRITICAL_EXCURSIONS DESC
LIMIT 10""")
add("How many returns were due to temperature excursions by DC and month in 2026?",
    'SELECT DATE_TRUNC(\'MONTH\', RETURN_DATE) AS RETURN_MONTH, DC_ID, COUNT(*) AS RETURNS, SUM(QTY_RETURNED) AS UNITS_RETURNED, ROUND(SUM(CREDIT_AMOUNT), 2) AS CREDIT_AMOUNT FROM "RETURNS" WHERE RETURN_REASON = \'TEMP_EXCURSION\' AND RETURN_DATE >= DATE \'2026-01-01\' GROUP BY RETURN_MONTH, DC_ID ORDER BY RETURN_MONTH, DC_ID')

# ---------------------------------------------------------------- inventory
add("Where do we have the most inventory value expiring in the next 90 days?",
    'SELECT DC_NAME, PRODUCT_NAME, THERAPEUTIC_CLASS, ON_HAND_UNITS, EXPIRING_90D_UNITS, EXPIRING_90D_VALUE_WAC, DAYS_OF_SUPPLY, AVG_WEEKLY_DEMAND_UNITS, ON_ORDER_UNITS, IS_EXPIRY_WRITE_OFF_RISK FROM "V_INVENTORY_RISK" ORDER BY EXPIRING_90D_VALUE_WAC DESC LIMIT 15')
add("Which DC and product combinations are at risk of an expiry write off?",
    'SELECT DC_NAME, PRODUCT_NAME, MANUFACTURER_NAME, EXPIRING_90D_UNITS, EXPIRING_90D_VALUE_WAC, AVG_WEEKLY_DEMAND_UNITS, DAYS_OF_SUPPLY, ON_ORDER_UNITS FROM "V_INVENTORY_RISK" WHERE IS_EXPIRY_WRITE_OFF_RISK = 1 ORDER BY EXPIRING_90D_VALUE_WAC DESC')
add("Show Oncaryl inventory and demand at Dallas by week since April.",
    'SELECT SNAPSHOT_DATE, ON_HAND_UNITS, AVAILABLE_UNITS, ON_ORDER_UNITS, AVG_WEEKLY_DEMAND_UNITS, DAYS_OF_SUPPLY, EXPIRING_90D_UNITS, EXPIRING_90D_VALUE_WAC FROM "INVENTORY_SNAPSHOTS" WHERE DC_ID = \'DC-DAL\' AND NDC = \'58771-0410-01\' AND SNAPSHOT_DATE >= DATE \'2026-04-01\' ORDER BY SNAPSHOT_DATE')
add("How has monthly Oncaryl demand from Dallas served sites changed in 2026?",
    'SELECT ORDER_MONTH, SUM(QTY_ORDERED) AS UNITS_ORDERED, COUNT(DISTINCT CUSTOMER_ID) AS ORDERING_CUSTOMERS FROM "V_ORDER_LINE_DETAIL" WHERE PRODUCT_NAME = \'Oncaryl\' AND DC_ID = \'DC-DAL\' AND ORDER_DATE >= DATE \'2026-01-01\' GROUP BY ORDER_MONTH ORDER BY ORDER_MONTH')
add("Which customers served by Dallas are still ordering Oncaryl and could take short dated stock?",
    'SELECT C.CUSTOMER_NAME, C.CUSTOMER_TYPE, C.HQ_CITY, SUM(L.QTY_ORDERED) AS UNITS_ORDERED_SINCE_JUNE, COUNT(*) AS LINES, MAX(L.ORDER_DATE) AS LAST_ORDER_DATE FROM "V_ORDER_LINE_DETAIL" AS L JOIN "CUSTOMERS" AS C ON C.CUSTOMER_ID = L.CUSTOMER_ID WHERE L.PRODUCT_NAME = \'Oncaryl\' AND L.DC_ID = \'DC-DAL\' AND L.ORDER_DATE >= DATE \'2026-06-01\' GROUP BY C.CUSTOMER_NAME, C.CUSTOMER_TYPE, C.HQ_CITY ORDER BY UNITS_ORDERED_SINCE_JUNE DESC')
add("Which products are at stockout risk at any DC right now?",
    'SELECT DC_NAME, PRODUCT_NAME, THERAPEUTIC_CLASS, AVAILABLE_UNITS, AVG_WEEKLY_DEMAND_UNITS, DAYS_OF_SUPPLY, ON_ORDER_UNITS FROM "V_INVENTORY_RISK" WHERE IS_STOCKOUT_RISK = 1 ORDER BY DAYS_OF_SUPPLY, AVG_WEEKLY_DEMAND_UNITS DESC LIMIT 20')
add("What is our total on hand inventory value by DC and how much of it expires within 90 days?",
    'SELECT DC_NAME, ROUND(SUM(INVENTORY_VALUE_WAC), 2) AS INVENTORY_VALUE_WAC, ROUND(SUM(EXPIRING_90D_VALUE_WAC), 2) AS EXPIRING_90D_VALUE_WAC, ROUND(SUM(EXPIRING_90D_VALUE_WAC) / NULLIF(SUM(INVENTORY_VALUE_WAC), 0), 4) AS EXPIRING_SHARE FROM "V_INVENTORY_RISK" GROUP BY DC_NAME ORDER BY EXPIRING_90D_VALUE_WAC DESC')

# ---------------------------------------------------------------- chargebacks
add("Which manufacturers have the highest chargeback dispute rate since May 2026?",
    'SELECT MANUFACTURER_NAME, SUM(CLAIMS) AS CLAIMS, SUM(DISPUTED_OR_REJECTED_CLAIMS) AS DISPUTED_OR_REJECTED_CLAIMS, ROUND(SUM(DISPUTED_OR_REJECTED_CLAIMS) / NULLIF(SUM(CLAIMS), 0), 4) AS DISPUTE_RATE, ROUND(SUM(AMOUNT_DISPUTED_OR_REJECTED), 2) AS AMOUNT_DISPUTED_OR_REJECTED FROM "V_CHARGEBACK_SUMMARY" WHERE SUBMITTED_MONTH >= DATE \'2026-05-01\' GROUP BY MANUFACTURER_NAME ORDER BY DISPUTE_RATE DESC')
add("Show the monthly chargeback dispute rate for Keldon Pharma in 2026.",
    'SELECT SUBMITTED_MONTH, CLAIMS, DISPUTED_OR_REJECTED_CLAIMS, DISPUTE_RATE, AMOUNT_CLAIMED, AMOUNT_DISPUTED_OR_REJECTED, AVG_DAYS_TO_SETTLE FROM "V_CHARGEBACK_SUMMARY" WHERE MANUFACTURER_NAME = \'Keldon Pharma\' AND SUBMITTED_MONTH >= DATE \'2026-01-01\' ORDER BY SUBMITTED_MONTH')
add("What are the dispute reasons on Keldon Pharma chargebacks since the April price file?",
    'SELECT DISPUTE_REASON, PRICE_FILE_VERSION, COUNT(*) AS CLAIMS, ROUND(SUM(CHARGEBACK_AMOUNT), 2) AS CHARGEBACK_AMOUNT FROM "CHARGEBACKS" WHERE MANUFACTURER_ID = \'MFR-002\' AND SUBMITTED_DATE >= DATE \'2026-04-15\' AND DISPUTE_REASON IS NOT NULL GROUP BY DISPUTE_REASON, PRICE_FILE_VERSION ORDER BY CLAIMS DESC')
add("How much Keldon Pharma chargeback money is currently disputed or rejected and which GPO contracts are involved?",
    """SELECT G.GPO_NAME, CB.STATUS, COUNT(*) AS CLAIMS, ROUND(SUM(CB.CHARGEBACK_AMOUNT), 2) AS CHARGEBACK_AMOUNT
FROM "CHARGEBACKS" AS CB
LEFT JOIN "GPOS" AS G ON G.GPO_ID = CB.GPO_ID
WHERE CB.MANUFACTURER_ID = 'MFR-002' AND CB.STATUS IN ('DISPUTED', 'REJECTED') AND CB.SUBMITTED_DATE >= DATE '2026-04-15'
GROUP BY G.GPO_NAME, CB.STATUS
ORDER BY CHARGEBACK_AMOUNT DESC""")
add("What is our overall chargeback recovery position this year?",
    'SELECT STATUS, COUNT(*) AS CLAIMS, ROUND(SUM(CHARGEBACK_AMOUNT), 2) AS CHARGEBACK_AMOUNT FROM "CHARGEBACKS" WHERE SUBMITTED_DATE >= DATE \'2026-01-01\' GROUP BY STATUS ORDER BY CHARGEBACK_AMOUNT DESC')
add("Compare Keldon Pharma dispute rate before and after the April 2026 price file.",
    """SELECT CASE WHEN SUBMITTED_DATE >= DATE '2026-04-15' THEN 'After 2026-04A price file' ELSE 'Before 2026-04A price file' END AS PERIOD,
       COUNT(*) AS CLAIMS,
       SUM(CASE WHEN STATUS IN ('DISPUTED', 'REJECTED') THEN 1 ELSE 0 END) AS DISPUTED_OR_REJECTED,
       ROUND(SUM(CASE WHEN STATUS IN ('DISPUTED', 'REJECTED') THEN 1 ELSE 0 END) / NULLIF(COUNT(*), 0), 4) AS DISPUTE_RATE
FROM "CHARGEBACKS"
WHERE MANUFACTURER_ID = 'MFR-002'
GROUP BY PERIOD
ORDER BY PERIOD""")

# ---------------------------------------------------------------- DC and channel performance
add("How is each DC performing on fill rate and on time delivery this year?",
    'SELECT DC_ID, DC_NAME, SUM(LINE_COUNT) AS LINES, ROUND(AVG(LINE_FILL_RATE), 4) AS AVG_LINE_FILL_RATE, ROUND(AVG(ON_TIME_DELIVERY_RATE), 4) AS AVG_ON_TIME_DELIVERY_RATE, SUM(EXCURSION_COUNT) AS EXCURSIONS FROM "V_DC_SERVICE_PERFORMANCE" WHERE MONTH >= DATE \'2026-01-01\' GROUP BY DC_ID, DC_NAME ORDER BY AVG_LINE_FILL_RATE DESC')
add("Show monthly on time delivery rate by DC for 2026.",
    'SELECT MONTH, DC_ID, ON_TIME_DELIVERY_RATE, SHIPMENT_COUNT FROM "V_DC_SERVICE_PERFORMANCE" WHERE MONTH >= DATE \'2026-01-01\' ORDER BY MONTH, DC_ID')
add("Do auto replenishment sites get better service than sites ordering by EDI or portal?",
    'SELECT ORDER_CHANNEL, COUNT(*) AS LINES, ROUND(SUM(IS_LINE_FILLED_COMPLETE) / NULLIF(COUNT(*), 0), 4) AS LINE_FILL_RATE, ROUND(SUM(CASE WHEN ORDER_PRIORITY = \'STAT\' THEN 1 ELSE 0 END) / NULLIF(COUNT(*), 0), 4) AS STAT_ORDER_SHARE, ROUND(SUM(IS_SHIPPED_ON_TIME) / NULLIF(SUM(CASE WHEN ACTUAL_SHIP_DATE IS NOT NULL THEN 1 ELSE 0 END), 0), 4) AS ON_TIME_SHIP_RATE FROM "V_ORDER_LINE_DETAIL" WHERE LINE_STATUS <> \'CANCELLED\' GROUP BY ORDER_CHANNEL ORDER BY LINE_FILL_RATE DESC')
add("Which strategic and key customers have the fewest sites on auto replenishment?",
    'SELECT C.CUSTOMER_NAME, C.CUSTOMER_TIER, COUNT(*) AS SITES, SUM(CASE WHEN S.ORDERING_CHANNEL = \'AUTO_REPLENISH\' THEN 1 ELSE 0 END) AS AUTO_REPLENISH_SITES, ROUND(SUM(CASE WHEN S.ORDERING_CHANNEL = \'AUTO_REPLENISH\' THEN 1 ELSE 0 END) / NULLIF(COUNT(*), 0), 4) AS AUTO_REPLENISH_SHARE FROM "CUSTOMER_SITES" AS S JOIN "CUSTOMERS" AS C ON C.CUSTOMER_ID = S.CUSTOMER_ID WHERE C.CUSTOMER_TIER IN (\'STRATEGIC\', \'KEY\') GROUP BY C.CUSTOMER_NAME, C.CUSTOMER_TIER HAVING COUNT(*) >= 4 ORDER BY AUTO_REPLENISH_SHARE, SITES DESC LIMIT 10')

# ---------------------------------------------------------------- service
add("What is our service case SLA attainment by severity this year?",
    'SELECT SEVERITY, COUNT(*) AS CLOSED_CASES, ROUND(SUM(CASE WHEN SLA_MET THEN 1 ELSE 0 END) / NULLIF(COUNT(*), 0), 4) AS SLA_ATTAINMENT, ROUND(AVG(RESOLUTION_HOURS), 1) AS AVG_RESOLUTION_HOURS FROM "SERVICE_CASES" WHERE STATUS = \'CLOSED\' AND OPENED_DATE >= DATE \'2026-01-01\' GROUP BY SEVERITY ORDER BY SEVERITY')
add("Which customers have escalated to executives in the last 90 days?",
    'SELECT C.CUSTOMER_NAME, C.CUSTOMER_TIER, C.CONTRACT_RENEWAL_DATE, COUNT(*) AS EXEC_ESCALATIONS, MAX(S.OPENED_DATE) AS LAST_ESCALATION_DATE FROM "SERVICE_CASES" AS S JOIN "CUSTOMERS" AS C ON C.CUSTOMER_ID = S.CUSTOMER_ID WHERE S.ESCALATED_TO_EXEC = TRUE AND S.OPENED_DATE >= DATE \'2026-06-27\' GROUP BY C.CUSTOMER_NAME, C.CUSTOMER_TIER, C.CONTRACT_RENEWAL_DATE ORDER BY EXEC_ESCALATIONS DESC')
add("What types of service cases are open right now and how severe are they?",
    'SELECT CASE_TYPE, SEVERITY, COUNT(*) AS OPEN_CASES FROM "SERVICE_CASES" WHERE STATUS <> \'CLOSED\' GROUP BY CASE_TYPE, SEVERITY ORDER BY OPEN_CASES DESC')
